    /* Mobile Header */
    .mobile-header-container {
        --mobile-header-height: 74px;
    }

    .mobile-header-container .mobile-header {
        display: flex;
        justify-content: flex-start;
        align-items: center;
        gap: 14px;
        min-height: var(--mobile-header-height);
        padding: 10px 16px;
        position: fixed;
        top: 0;
        width: 100%;
        background: rgba(255, 250, 245, 0.96);
        backdrop-filter: blur(12px);
        box-shadow: 0 8px 18px rgba(90, 67, 49, 0.06);
        z-index: 1000;
        border-bottom: 1px solid rgba(154, 90, 69, 0.08);
        box-sizing: border-box;
    }

    .mobile-header-container .mobile-header .logo {
        min-width: 0;
        flex: 1 1 auto;
    }

    .mobile-header-container .mobile-header .logo a {
        display: block;
    }

    .mobile-header-container .mobile-header .logo h1 {
        margin: 0;
        font-size: 18px;
        line-height: 1.2;
        letter-spacing: 0.04em;
        color: var(--brand-red-deep);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    /* Hamburger and Close button */
    .mobile-header-container .mobile-header .hamburger-menu,
    .mobile-header-container .mobile-header .close-menu {
        display: flex;
        align-items: center;
        justify-content: center;
        flex: 0 0 auto;
        width: 44px;
        height: 44px;
        border-radius: 999px;
        background: rgba(111, 52, 48, 0.08);
        border: 1px solid rgba(111, 52, 48, 0.08);
        font-size: 28px;
        line-height: 1;
        cursor: pointer;
        color: var(--brand-red-deep);
        transition: background-color 0.25s ease, transform 0.3s ease;
    }

    /* Initially hide the close button */
    .mobile-header-container .mobile-header .close-menu {
        display: none;
    }

    /* Overlay */
    .mobile-header-container .mobile-menu-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.5);
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.3s ease, visibility 0.3s ease;
        z-index: 999;
    }

    .mobile-header-container .mobile-menu-overlay.open {
        opacity: 1;
        visibility: visible;
    }

    /* Slide-out Menu */
    .mobile-header-container .mobile-menu {
        position: fixed;
        top: 0;
        left: -100%;
        width: min(82vw, 340px);
        height: 100%;
        background: linear-gradient(180deg, #fffaf6, #f8eee6);
        overflow-y: auto;
        z-index: 1000;
        box-shadow: 8px 0 24px rgba(90, 67, 49, 0.12);
        transition: left 0.3s ease-in-out;
    }

    .mobile-header-container .mobile-menu.open {
        left: 0;
    }

    /* Styling Menu Items */
    .mobile-header-container .mobile-menu .mobile-menu-list {
        list-style: none;
        padding: 92px 18px 24px;
        margin: 0;
    }

    .mobile-header-container .mobile-menu .mobile-menu-list>li {
        margin-bottom: 0;
        border-bottom: 1px solid rgba(154, 90, 69, 0.08);
        padding-bottom: 0;
    }

    .mobile-header-container .mobile-menu .mobile-menu-list>li>a {
        text-decoration: none;
        font-size: 19px;
        font-weight: 700;
        color: var(--brand-ink);
        padding: 14px 0;
        display: block;
        background-color: transparent;
        transition: background-color 0.3s ease, padding-left 0.3s ease;
    }

    .mobile-header-container .mobile-menu .mobile-menu-list>li>a:hover {
        background-color: rgba(154, 90, 69, 0.05);
        padding-left: 12px;
    }

    /* Styling for Submenu */
    .mobile-header-container .mobile-menu .submenu {
        list-style: none;
        padding-left: 20px;
        margin-top: 0;
        margin-bottom: 0;
    }

    .mobile-header-container .mobile-menu .submenu>li {
        border-bottom: 1px solid rgba(154, 90, 69, 0.06);
        padding-bottom: 0;
        margin-bottom: 0;
    }

    .mobile-header-container .mobile-menu .submenu>li>a {
        text-decoration: none;
        font-size: 16px;
        color: #7b4a2b;
        padding: 6px 0;
        display: block;
        transition: background-color 0.3s ease, padding-left 0.3s ease;
    }

    .mobile-header-container .mobile-menu .submenu>li>a:hover {
        background-color: rgba(240, 191, 82, 0.08);
        padding-left: 12px;
    }

    /* Hide Hamburger, Show Close Button when menu is open */
    .mobile-header-container .mobile-header .hamburger-menu.open {
        display: none;
    }

    .mobile-header-container .mobile-header .close-menu.open {
        display: block;
    }

    /* Hide the hamburger icon on desktop */
    @media (max-width: 769px) {
        .mobile-header-container {
            display: block;
        }

        .content {
            padding-top: calc(var(--mobile-header-height) + 12px);
        }
    }

    @media (max-width: 960px) {
        .overhead .container {
            flex-direction: column;
            align-items: flex-start;
        }

        .contact-info span,
        .social-icons span {
            width: 100%;
            justify-content: flex-start;
        }
    }
</style>


